window.CHAPTERS.push({view:'ch3', no:3, title:'기획자의 몸값 — 가치를 만드는 사람의 기술', desc:'같은 기획을 해도 몸값이 차이나는 이유 — 부가가치 전략(치환가치 · 리스크 경감 가치 · 감동가치), 숫자 너머 고객의 심리를 읽는 기획자의 심리학, 속도를 높이는 업무 추진법(3시간 업무 구분법 · 세 가지 체크리스트 · 기대치 조정), 작은 실수도 없는 품질(괄호 · 오탈자 · 용어), PEST로 방향을 잡는 리더의 매크로적 시각, 보고 대상을 깊게 아는 마이크로적 접근과 SMART한 숫자까지 — 기획자 자신의 가치를 올리는 기술을 다뤄요.', PARTS, T});
